fn fd_demo(vfs: Endpoint) {
    let a = vfs_open(vfs, ROOTFS_MOTD_PATH);
    let b = vfs_open(vfs, ROOTFS_MOTD_PATH);
    let closed_a = vfs_close(vfs, a);
