    let again = vfs_open(vfs, ROOTFS_MOTD_PATH);

    let ok = a == 3 && b == 4 && closed_a == OK && closed_b == OK && again == 3;
    let _ = vfs_close(vfs, again);
    let _ = vfs_write(
